def disjoint_set(expression: str) -> str:
    """Convert an infix expression to postfix (Reverse Polish) notation.

    Supports: +, -, *, /, ^, parentheses, and multi-digit/decimal numbers.
    """
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
    right_assoc = {'^'}
    output = []
    stack = []

    tokens = _tokenize(expression)

    for token in tokens:
        if _is_number(token):
            output.append(token)
        elif token == '(':
            stack.append(token)
        elif token == ')':
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            if not stack:
                raise ValueError("Mismatched parentheses")
            stack.pop()  # discard '('
        elif token in precedence:
            while (stack and stack[-1] != '('
                   and stack[-1] in precedence
                   and (precedence[stack[-1]] > precedence[token]
                        or (precedence[stack[-1]] == precedence[token]
                            and token not in right_assoc))):
                output.append(stack.pop())
            stack.append(token)
        else:
            raise ValueError(f"Unknown token: {token}")

    while stack:
        if stack[-1] == '(':
            raise ValueError("Mismatched parentheses")
        output.append(stack.pop())

    return ' '.join(output)


def _tokenize(expression: str) -> list[str]:
    tokens = []
    i = 0
    while i < len(expression):
        ch = expression[i]
        if ch.isspace():
            i += 1
            continue
        if ch.isdigit() or ch == '.':
            j = i
            while j < len(expression) and (expression[j].isdigit() or expression[j] == '.'):
                j += 1
            tokens.append(expression[i:j])
            i = j
        elif ch in '+-*/^()':
            tokens.append(ch)
            i += 1
        else:
            raise ValueError(f"Invalid character: {ch}")
    return tokens


def _is_number(token: str) -> bool:
    try:
        float(token)
        return True
    except ValueError:
        return False


# ── Tests ────────────────────────────────────────────────────────────────────

def test_basic_operators():
    assert disjoint_set("3 + 4") == "3 4 +"
    assert disjoint_set("10 - 2") == "10 2 -"
    assert disjoint_set("5 * 6") == "5 6 *"
    assert disjoint_set("8 / 4") == "8 4 /"


def test_precedence():
    # * binds tighter than +
    assert disjoint_set("3 + 4 * 5") == "3 4 5 * +"
    assert disjoint_set("3 * 4 + 5") == "3 4 * 5 +"
    # / binds tighter than -
    assert disjoint_set("10 - 6 / 2") == "10 6 2 / -"


def test_left_associativity():
    # + and - are left-associative
    assert disjoint_set("10 - 3 - 2") == "10 3 - 2 -"
    assert disjoint_set("8 / 4 / 2") == "8 4 / 2 /"


def test_right_associativity():
    # ^ is right-associative: 2^3^2 = 2^(3^2) = 2^9
    assert disjoint_set("2 ^ 3 ^ 2") == "2 3 2 ^ ^"


def test_parentheses():
    assert disjoint_set("(3 + 4) * 5") == "3 4 + 5 *"
    assert disjoint_set("3 * (4 + 5)") == "3 4 5 + *"
    assert disjoint_set("(1 + 2) * (3 + 4)") == "1 2 + 3 4 + *"


def test_nested_parentheses():
    assert disjoint_set("((1 + 2) * 3)") == "1 2 + 3 *"
    assert disjoint_set("((2 + 3) * (4 - 1)) / 5") == "2 3 + 4 1 - * 5 /"


def test_multi_digit_numbers():
    assert disjoint_set("12 + 34") == "12 34 +"
    assert disjoint_set("100 * 200 + 300") == "100 200 * 300 +"


def test_decimal_numbers():
    assert disjoint_set("3.5 + 2.1") == "3.5 2.1 +"
    assert disjoint_set("1.5 * 2") == "1.5 2 *"


def test_complex_expression():
    # a classic textbook example
    assert disjoint_set("3 + 4 * 2 / (1 - 5) ^ 2 ^ 3") == "3 4 2 * 1 5 - 2 3 ^ ^ / +"


def test_single_number():
    assert disjoint_set("42") == "42"


def test_mismatched_parentheses():
    import pytest
    with pytest.raises(ValueError, match="Mismatched"):
        disjoint_set("(3 + 4")
    with pytest.raises(ValueError, match="Mismatched"):
        disjoint_set("3 + 4)")


def test_invalid_character():
    import pytest
    with pytest.raises(ValueError, match="Invalid character"):
        disjoint_set("3 & 4")


