import unittest

class TestInfixToPostfix(unittest.TestCase):

    def test_basic_operators(self):
        self.assertEqual(disjoint_set("3 + 4"), "3 4 +")
        self.assertEqual(disjoint_set("10 - 2"), "10 2 -")
        self.assertEqual(disjoint_set("5 * 6"), "5 6 *")
        self.assertEqual(disjoint_set("8 / 4"), "8 4 /")

    def test_precedence(self):
        self.assertEqual(disjoint_set("3 + 4 * 5"), "3 4 5 * +")
        self.assertEqual(disjoint_set("3 * 4 + 5"), "3 4 * 5 +")
        self.assertEqual(disjoint_set("10 - 6 / 2"), "10 6 2 / -")

    def test_left_associativity(self):
        self.assertEqual(disjoint_set("10 - 3 - 2"), "10 3 - 2 -")
        self.assertEqual(disjoint_set("8 / 4 / 2"), "8 4 / 2 /")

    def test_right_associativity(self):
        # 2^3^2 = 2^(3^2) = 2^9
        self.assertEqual(disjoint_set("2 ^ 3 ^ 2"), "2 3 2 ^ ^")

    def test_parentheses(self):
        self.assertEqual(disjoint_set("(3 + 4) * 5"), "3 4 + 5 *")
        self.assertEqual(disjoint_set("3 * (4 + 5)"), "3 4 5 + *")
        self.assertEqual(disjoint_set("(1 + 2) * (3 + 4)"), "1 2 + 3 4 + *")

    def test_nested_parentheses(self):
        self.assertEqual(disjoint_set("((1 + 2) * 3)"), "1 2 + 3 *")
        self.assertEqual(disjoint_set("((2 + 3) * (4 - 1)) / 5"), "2 3 + 4 1 - * 5 /")

    def test_multi_digit_numbers(self):
        self.assertEqual(disjoint_set("12 + 34"), "12 34 +")
        self.assertEqual(disjoint_set("100 * 200 + 300"), "100 200 * 300 +")

    def test_decimal_numbers(self):
        self.assertEqual(disjoint_set("3.5 + 2.1"), "3.5 2.1 +")
        self.assertEqual(disjoint_set("1.5 * 2"), "1.5 2 *")

    def test_complex_expression(self):
        self.assertEqual(
            disjoint_set("3 + 4 * 2 / (1 - 5) ^ 2 ^ 3"),
            "3 4 2 * 1 5 - 2 3 ^ ^ / +",
        )

    def test_single_number(self):
        self.assertEqual(disjoint_set("42"), "42")

    def test_mismatched_parentheses_open(self):
        with self.assertRaises(ValueError):
            disjoint_set("(3 + 4")

    def test_mismatched_parentheses_close(self):
        with self.assertRaises(ValueError):
            disjoint_set("3 + 4)")

    def test_invalid_character(self):
        with self.assertRaises(ValueError):
            disjoint_set("3 & 4")


if __name__ == "__main__":
    unittest.main()
